void CostmapGenerator::onLaneletMapBin(
  const autoware_map_msgs::msg::LaneletMapBin::ConstSharedPtr msg)
{
  lanelet_map_ = autoware::experimental::lanelet2_utils::remove_const(
    autoware::experimental::lanelet2_utils::from_autoware_map_msgs(*msg));

  if (param_->use_wayarea) {
    loadRoadAreasFromLaneletMap(lanelet_map_, primitives_polygons_);
  }

  if (param_->use_parkinglot) {
    loadParkingAreasFromLaneletMap(lanelet_map_, primitives_polygons_);
  }
}

lanelet::LaneletMapConstPtr from_autoware_map_msgs(
  const autoware_map_msgs::msg::LaneletMapBin & msg)
{
  std::string data_str;
  data_str.assign(msg.data.begin(), msg.data.end());

  std::stringstream ss;
  ss << data_str;
  boost::archive::binary_iarchive oa(ss);

  auto lanelet_map_ptr = std::make_shared<lanelet::LaneletMap>();
  oa >> *lanelet_map_ptr;
  lanelet::Id id_counter = 0;
  oa >> id_counter;
  lanelet::utils::registerId(id_counter);

  return lanelet_map_ptr;
}

void CostmapGenerator::loadRoadAreasFromLaneletMap(
  const lanelet::LaneletMapPtr lanelet_map,
  std::vector<geometry_msgs::msg::Polygon> & area_polygons)
{
  // use all lanelets in map of subtype road to give way area
  lanelet::ConstLanelets all_lanelets = lanelet::utils::query::laneletLayer(lanelet_map);
  lanelet::ConstLanelets road_lanelets = lanelet::utils::query::roadLanelets(all_lanelets);

  // convert lanelets to polygons and put into area_points array
  for (const auto & ll : road_lanelets) {
    geometry_msgs::msg::Polygon poly;
    for (const auto & p : ll.polygon3d().basicPolygon()) {
      const auto pt = experimental::lanelet2_utils::to_ros(p);
      poly.points.push_back(
        geometry_msgs::build<geometry_msgs::msg::Point32>().x(pt.x).y(pt.y).z(pt.z));
    }
    area_polygons.push_back(poly);
  }
}

lanelet::ConstLanelets query::laneletLayer(const lanelet::LaneletMapConstPtr & ll_map)
{
  lanelet::ConstLanelets lanelets;
  if (!ll_map) {
    std::cerr << "No map received!";
    return lanelets;
  }

  for (const auto & li : ll_map->laneletLayer) {
    lanelets.push_back(li);
  }

  return lanelets;
}

lanelet::ConstLanelets query::roadLanelets(const lanelet::ConstLanelets & lls)
{
  return query::subtypeLanelets(lls, lanelet::AttributeValueString::Road);
}

lanelet::ConstLanelets query::subtypeLanelets(
  const lanelet::ConstLanelets & lls, const char subtype[])
{
  lanelet::ConstLanelets subtype_lanelets;

  for (const auto & ll : lls) {
    if (ll.hasAttribute(lanelet::AttributeName::Subtype)) {
      const lanelet::Attribute & attr = ll.attribute(lanelet::AttributeName::Subtype);
      if (attr.value() == subtype) {
        subtype_lanelets.push_back(ll);
      }
    }
  }

  return subtype_lanelets;
}

const Attribute& attribute(const std::string& name) const {
  try {
    return attributes().at(name);
  } catch (std::out_of_range& err) {
    throw NoSuchAttributeError(err.what());
  }
}

