geometry_msgs::msg::Point to_ros(const lanelet::BasicPoint3d & src)
{
  geometry_msgs::msg::Point dst;
  dst.x = src.x();
  dst.y = src.y();
  dst.z = src.z();
  return dst;
}

void CostmapGenerator::loadParkingAreasFromLaneletMap(
  const lanelet::LaneletMapPtr lanelet_map,
  std::vector<geometry_msgs::msg::Polygon> & area_polygons)
{
  // Parking lots
  auto toGeomMsgPoly =
    [](const lanelet::ConstPolygon3d & ll_poly, geometry_msgs::msg::Polygon * geom_poly) {
      geom_poly->points.clear();
      geom_poly->points.reserve(ll_poly.size());
      for (const auto & ll_pt : ll_poly) {
        const auto geom_pt = experimental::lanelet2_utils::to_ros(ll_pt.basicPoint());
        geom_poly->points.push_back(
          geometry_msgs::build<geometry_msgs::msg::Point32>()
            .x(static_cast<float>(geom_pt.x))
            .y(static_cast<float>(geom_pt.y))
            .z(static_cast<float>(geom_pt.z)));
      }
    };

  lanelet::ConstPolygons3d all_parking_lots = lanelet::utils::query::getAllParkingLots(lanelet_map);
  for (const auto & ll_poly : all_parking_lots) {
    geometry_msgs::msg::Polygon poly;
    toGeomMsgPoly(ll_poly, &poly);
    area_polygons.push_back(poly);
  }

  // Parking spaces
  lanelet::ConstLineStrings3d all_parking_spaces =
    lanelet::utils::query::getAllParkingSpaces(lanelet_map);
  for (const auto & parking_space : all_parking_spaces) {
    lanelet::ConstPolygon3d ll_poly;
    lanelet::utils::lineStringWithWidthToPolygon(parking_space, &ll_poly);
    geometry_msgs::msg::Polygon poly;
    toGeomMsgPoly(ll_poly, &poly);
    area_polygons.push_back(poly);
  }
}

lanelet::ConstPolygons3d getAllParkingLots(const lanelet::LaneletMapConstPtr & lanelet_map_ptr)
{
  lanelet::ConstPolygons3d parking_lots;
  for (const auto & poly : lanelet_map_ptr->polygonLayer) {
    const std::string type = poly.attributeOr(lanelet::AttributeName::Type, "none");
    if (type == "parking_lot") {
      parking_lots.push_back(poly);
    }
  }
  return parking_lots;
}

T attributeOr(AttributeName name, T defaultVal) const {
  auto elem = attributes().find(name);
  if (elem == attributes().end()) {
    return defaultVal;
  }
  auto val = elem->second.template as<T>();
  if (!!val) {
    return *val;
  }
  return defaultVal;
}

auto toGeomMsgPoly =
  [](const lanelet::ConstPolygon3d & ll_poly, geometry_msgs::msg::Polygon * geom_poly) {
    geom_poly->points.clear();
    geom_poly->points.reserve(ll_poly.size());
    for (const auto & ll_pt : ll_poly) {
      const auto geom_pt = experimental::lanelet2_utils::to_ros(ll_pt.basicPoint());
      geom_poly->points.push_back(
        geometry_msgs::build<geometry_msgs::msg::Point32>()
          .x(static_cast<float>(geom_pt.x))
          .y(static_cast<float>(geom_pt.y))
          .z(static_cast<float>(geom_pt.z)));
    }
  };

